{
  "status": "success",
  "tool": {
    "id": "pdb-toolkit",
    "name": "PDB Experimental Structure Database",
    "description": "Access experimentally determined protein structures from X-ray crystallography, NMR, and cryo-EM. Best for high-resolution experimental structures and validation data. Use AlphaFold for predicted structures.",
    "category": "database",
    "parameters": [
      {
        "name": "operation",
        "type": "select",
        "required": true,
        "description": "Type of PDB operation to perform",
        "options": [
          "search",
          "fetch",
          "metadata",
          "structure",
          "ligand",
          "download-coordinates",
          "download-bcif",
          "visualization"
        ]
      },
      {
        "name": "pdb_id",
        "type": "string",
        "required": false,
        "description": "PDB structure identifier (4-character code, e.g., 1INS, 2XYZ). Required for metadata/fetch/structure/ligand/download operations; omit for search.",
        "placeholder": "e.g., 1INS, 2XYZ, 3ABC",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "fetch",
            "metadata",
            "structure",
            "ligand",
            "download-coordinates",
            "download-bcif",
            "visualization"
          ]
        }
      },
      {
        "name": "query",
        "type": "textarea",
        "required": false,
        "description": "Search terms for structure discovery (required for the search operation only)",
        "placeholder": "e.g., insulin human, BRCA1 cancer, kinase inhibitor",
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "search_type",
        "type": "select",
        "required": false,
        "description": "Type of search to perform",
        "options": [
          "text",
          "sequence",
          "structure",
          "chemical"
        ],
        "defaultValue": "text",
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "format",
        "type": "select",
        "required": false,
        "description": "Coordinate file format",
        "options": [
          "cif",
          "bcif",
          "pdb",
          "mmcif"
        ],
        "defaultValue": "cif",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "download-coordinates",
            "structure"
          ]
        }
      },
      {
        "name": "encoding",
        "type": "select",
        "required": false,
        "description": "Data encoding format",
        "options": [
          "cif",
          "bcif"
        ],
        "defaultValue": "cif",
        "showWhen": {
          "parameter": "operation",
          "value": "download-bcif"
        }
      },
      {
        "name": "assembly_id",
        "type": "string",
        "required": false,
        "description": "Assembly ID for biological assembly",
        "placeholder": "e.g., 1, 2, preferred",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "download-coordinates",
            "download-bcif",
            "visualization"
          ]
        }
      },
      {
        "name": "chain_id",
        "type": "string",
        "required": false,
        "description": "Chain identifier (e.g., A, B, C)",
        "placeholder": "e.g., A, B, C",
        "showWhen": {
          "parameter": "operation",
          "value": [
            "structure",
            "download-coordinates",
            "visualization"
          ]
        }
      },
      {
        "name": "ligand_id",
        "type": "string",
        "required": false,
        "description": "Ligand identifier (3-letter code)",
        "placeholder": "e.g., ATP, GTP, ZN",
        "showWhen": {
          "parameter": "operation",
          "value": "ligand"
        }
      },
      {
        "name": "representation",
        "type": "select",
        "required": false,
        "description": "3D representation style",
        "options": [
          "cartoon",
          "surface",
          "ball-and-stick",
          "spacefill",
          "ribbon"
        ],
        "defaultValue": "cartoon",
        "showWhen": {
          "parameter": "operation",
          "value": "visualization"
        }
      },
      {
        "name": "color_scheme",
        "type": "select",
        "required": false,
        "description": "Color scheme for visualization",
        "options": [
          "chain",
          "element",
          "residue",
          "secondary-structure",
          "hydrophobicity"
        ],
        "defaultValue": "chain",
        "showWhen": {
          "parameter": "operation",
          "value": "visualization"
        }
      },
      {
        "name": "max_results",
        "type": "number",
        "required": false,
        "description": "Maximum number of search results",
        "defaultValue": 50,
        "min": 1,
        "max": 1000,
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "resolution_range",
        "type": "string",
        "required": false,
        "description": "Resolution range filter (e.g., 0.5-2.0)",
        "placeholder": "e.g., 0.5-2.0",
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "experimental_method",
        "type": "select",
        "required": false,
        "description": "Experimental method filter",
        "options": [
          "X-RAY DIFFRACTION",
          "SOLUTION NMR",
          "ELECTRON MICROSCOPY",
          "NEUTRON DIFFRACTION",
          "SOLID-STATE NMR"
        ],
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "organism",
        "type": "string",
        "required": false,
        "description": "Organism filter",
        "placeholder": "e.g., Homo sapiens, Escherichia coli",
        "showWhen": {
          "parameter": "operation",
          "value": "search"
        }
      },
      {
        "name": "download_file",
        "type": "boolean",
        "required": false,
        "description": "Download coordinate file to local storage",
        "defaultValue": false,
        "showWhen": {
          "parameter": "operation",
          "value": [
            "download-coordinates",
            "download-bcif"
          ]
        }
      }
    ],
    "executionMode": "instant",
    "version": "1.0.0",
    "author": "Bioinformatics Agent Team",
    "tags": [
      "structural",
      "proteomics",
      "genomics",
      "biochemistry",
      "biophysics"
    ]
  },
  "timestamp": "2026-11-04T08:31:33.692Z"
}

